\set ON_ERROR_STOP on
begin;
set local request.jwt.claim.role='service_role';
do $test$
declare
 actor constant uuid:='00000000-0000-4000-8000-000000000141';hq constant uuid:='14000000-0000-4000-8000-000000000001';dealer constant uuid:='24000000-0000-4000-8000-000000000001';branch constant uuid:='34000000-0000-4000-8000-000000000001';branch2 constant uuid:='34000000-0000-4000-8000-000000000002';account constant uuid:='44000000-0000-4000-8000-000000000001';fee constant uuid:='54000000-0000-4000-8000-000000000001';period_hq constant uuid:='74000000-0000-4000-8000-000000000001';period_branch constant uuid:='74000000-0000-4000-8000-000000000002';expense constant uuid:='64000000-0000-4000-8000-000000000001';journal constant uuid:='84000000-0000-4000-8000-000000000001';accrual constant uuid:='94000000-0000-4000-8000-000000000001';open_item constant uuid:='a4000000-0000-4000-8000-000000000001';batch constant uuid:='b4000000-0000-4000-8000-000000000001';batch_item constant uuid:='c4000000-0000-4000-8000-000000000001';invoice constant uuid:='d4000000-0000-4000-8000-000000000001';corr constant uuid:='e4000000-0000-4000-8000-000000000001';v jsonb;
begin
 insert into finance.legal_entities(id,entity_code,legal_name,status,created_by,correlation_id)values(hq,'OTOTR-HQ-ACCESS-DEMO','Sentetik Erişim Merkezi','ACTIVE',actor,corr);
 insert into finance.dealer_legal_entities(id,legal_entity_id,dealer_code,legal_name,status,created_by,correlation_id)values(dealer,hq,'ACCESS-DEALER','Sentetik Erişim Bayisi','ACTIVE',actor,corr);
 insert into finance.branches(id,legal_entity_id,dealer_legal_entity_id,branch_code,status,created_by,correlation_id)values(branch,hq,dealer,'ACCESS-A','ACTIVE',actor,corr),(branch2,hq,dealer,'ACCESS-B','ACTIVE',actor,corr);
 insert into finance.dealer_accounts(id,legal_entity_id,dealer_legal_entity_id,account_code,currency_code,status,created_by,correlation_id)values(account,hq,dealer,'ACCESS-ACCOUNT','TRY','ACTIVE',actor,corr);
 insert into finance.fee_definitions(id,legal_entity_id,code,version_no,fee_family,name,status,created_by,correlation_id)values(fee,hq,'ROYALTY_ACCESS',1,'ROYALTY','Royalty Hizmet Bedeli','PUBLISHED',actor,corr);
 insert into finance.finance_periods(id,legal_entity_id,scope_type,period_start,period_end,currency_code,mode,status,prepared_by,approved_by,locked_at_utc,created_by,correlation_id)values(period_hq,hq,'HEADQUARTERS',date'2026-11-01',date'2026-11-30','TRY','LIVE','LOCKED',actor,gen_random_uuid(),now(),actor,corr);
 insert into finance.finance_periods(id,legal_entity_id,parent_period_id,scope_type,dealer_account_id,branch_id,period_start,period_end,currency_code,mode,status,prepared_by,approved_by,locked_at_utc,created_by,correlation_id)values(period_branch,hq,period_hq,'BRANCH',account,branch,date'2026-11-01',date'2026-11-30','TRY','LIVE','LOCKED',actor,gen_random_uuid(),now(),actor,corr);
 insert into finance.pass_through_expenses(id,legal_entity_id,fee_definition_id,supplier_reference,supplier_reference_normalized,contractual_basis_reference,expense_date,currency_code,source_net_amount,source_tax_amount,source_amount,distributable_net_amount,distributable_tax_amount,distributable_amount,allocation_policy,evidence_object_key,evidence_hash,idempotency_key,input_hash,status,prepared_by,approved_by,created_by,correlation_id)values(expense,hq,fee,'ACCESS-SOURCE','ACCESS-SOURCE','ACCESS-BASIS',date'2026-11-03','TRY',100,20,120,100,20,120,'{"method":"SYNTHETIC"}'::jsonb,'synthetic/access.json',repeat('a',64),'access-source',repeat('b',64),'APPROVED',actor,gen_random_uuid(),actor,corr);
 insert into finance.journal_entries(id,legal_entity_id,finance_period_id,idempotency_key,intent_hash,entry_type,business_date,posting_date,status,posted_at_utc,posted_by,created_by,correlation_id)values(journal,hq,period_branch,'access-journal',repeat('c',64),'ACCRUAL',date'2026-11-03',date'2026-11-03','POSTED',now(),actor,actor,corr);
 insert into finance.accruals(id,legal_entity_id,pass_through_expense_id,dealer_account_id,branch_id,journal_entry_id,sequence_no,fee_definition_id,currency_code,net_amount,tax_amount,gross_amount,status,created_by,correlation_id)values(accrual,hq,expense,account,branch,journal,1,fee,'TRY',100,20,120,'POSTED',actor,corr);
 insert into finance.open_items(id,legal_entity_id,accrual_id,dealer_account_id,branch_id,due_date,currency_code,item_type,original_amount,allocated_amount,open_amount,status,created_by,correlation_id)values(open_item,hq,accrual,account,branch,date'2026-11-04','TRY','DEBIT',120,0,120,'OPEN',actor,corr);
 insert into finance.billing_batches(id,legal_entity_id,finance_period_id,dealer_account_id,branch_id,idempotency_key,intent_hash,batch_no,grouping_profile_code,currency_code,control_net,control_tax,control_gross,content_hash,status,created_by,correlation_id)values(batch,hq,period_branch,account,branch,'access-batch',repeat('d',64),'ACCESS-BATCH','ROYALTY-SINGLE-LINE','TRY',100,20,120,repeat('e',64),'INVOICED',actor,corr);
 insert into finance.billing_batch_items(id,billing_batch_id,accrual_id,net_amount,tax_amount,gross_amount,status,created_by,correlation_id)values(batch_item,batch,accrual,100,20,120,'ACTIVE',actor,corr);
 insert into finance.external_invoices(id,legal_entity_id,billing_batch_id,branch_id,idempotency_key,intent_hash,external_system,external_invoice_id,invoice_number,invoice_date,currency_code,net_amount,tax_amount,gross_amount,status,created_by,correlation_id)values(invoice,hq,batch,branch,'access-invoice',repeat('f',64),'SYNTHETIC_CARD','ACCESS-INV-001','OTOTR-ACCESS-001',date'2026-11-03','TRY',100,20,120,'ISSUED',actor,corr);
 insert into finance.external_invoice_lines(external_invoice_id,billing_batch_item_id,line_no,net_amount,tax_amount,gross_amount,created_by,correlation_id)values(invoice,batch_item,1,100,20,120,actor,corr);
 v:=finance_api.evaluate_branch_operation_access(actor,hq,account,branch,date'2026-11-05',corr);if v->>'accessState'<>'LOCKED_OVERDUE'or v->>'blockingInvoiceCount'<>'1'or v->>'blockingOpenAmount'<>'120.00000000'then raise exception'lock mismatch: %',v;end if;
 v:=finance_api.authorize_branch_operation_access(actor,hq,account,branch,'WORK_ORDER_WRITE',date'2026-11-05',corr);if(v->>'allowed')::boolean or v->>'denialCode'<>'BRANCH_FINANCE_LOCKED'then raise exception'operation was not denied: %',v;end if;
 v:=finance_api.authorize_branch_operation_access(actor,hq,account,branch,'PAYMENT',date'2026-11-05',corr);if not(v->>'allowed')::boolean then raise exception'payment was denied: %',v;end if;
 update finance.open_items set allocated_amount=80,open_amount=40,status='PARTIALLY_ALLOCATED',version=version+1 where id=open_item;
 v:=finance_api.authorize_branch_operation_access(actor,hq,account,branch,'WORK_ORDER_WRITE',date'2026-11-05',corr);if(v->>'allowed')::boolean or v->>'blockingOpenAmount'<>'40.00000000'then raise exception'partial payment unlocked branch: %',v;end if;
 update finance.open_items set allocated_amount=120,open_amount=0,status='CLOSED',version=version+1 where id=open_item;
 v:=finance_api.authorize_branch_operation_access(actor,hq,account,branch,'WORK_ORDER_WRITE',date'2026-11-05',corr);if not(v->>'allowed')::boolean or v->>'accessState'<>'OPEN'then raise exception'full payment did not unlock: %',v;end if;
 v:=finance_api.authorize_branch_operation_access(actor,hq,account,branch2,'WORK_ORDER_WRITE',date'2026-11-05',corr);if not(v->>'allowed')::boolean then raise exception'cross-branch isolation failed: %',v;end if;
 if(select count(*)from finance.outbox_messages where event_type='BRANCH_OPERATIONS_LOCKED_OVERDUE')<>1 or(select count(*)from finance.outbox_messages where event_type='BRANCH_OPERATIONS_UNLOCKED_PAYMENT_VERIFIED')<>1 then raise exception'access transition outbox mismatch';end if;
 if(select count(*)from finance.audit_events where action_code in('BRANCH_OPERATIONS_LOCKED_OVERDUE','BRANCH_OPERATIONS_UNLOCKED_PAYMENT_VERIFIED'))<>2 then raise exception'access transition audit mismatch';end if;
 raise notice'BRANCH OVERDUE ACCESS E2E PASSED: overdue lock, safe payment access, partial hold, full unlock and branch isolation';
end$test$;
rollback;
